{
  "name": "ManualAuto",
  "description": "Two-axis assembly with a manual and an automatic mode.",
  "version": "1.0.0",
  "variables": {
    "local": [
      {
        "name": "Auto",
        "type": "BOOL",
        "initialValue": false,
        "comment": "The mode: FALSE is manual, TRUE is automatic; the machine powers up in manual"
      },
      {
        "name": "ToAuto",
        "type": "BOOL",
        "initialValue": false,
        "comment": "A mode press while in manual"
      },
      {
        "name": "ToManual",
        "type": "BOOL",
        "initialValue": false,
        "comment": "A mode press while in automatic"
      },
      {
        "name": "Begin",
        "type": "BOOL",
        "initialValue": false,
        "comment": "A Start press that counts: only in automatic"
      },
      {
        "name": "Active",
        "type": "BOOL",
        "initialValue": false,
        "comment": "The assembly is on"
      },
      {
        "name": "Step",
        "type": "INT",
        "initialValue": 0,
        "comment": "0 idle, 1 home, 2 wait, 3 settle, 4 lower, 5 grip, 6 lift, 7 carry, 8 lower, 9 release, 10 raise, 11 return, 12 done"
      },
      {
        "name": "Cycles",
        "type": "INT",
        "initialValue": 0,
        "comment": "Assemblies finished"
      },
      {
        "name": "FreeBase",
        "type": "BOOL",
        "initialValue": false,
        "comment": "The base blade is open and the assembled base is leaving"
      },
      {
        "name": "SettleT",
        "type": "TON",
        "comment": "Wait before the pad lowers on the lid"
      },
      {
        "name": "GripT",
        "type": "TON",
        "comment": "Wait for the vacuum to take hold"
      },
      {
        "name": "LetGoT",
        "type": "TON",
        "comment": "Wait for the lid to settle on the base"
      },
      {
        "name": "BaseLeft",
        "type": "TON",
        "comment": "Wait for the assembled base to leave"
      },
      {
        "name": "LidGone",
        "type": "F_TRIG",
        "comment": "The pad has taken the lid"
      },
      {
        "name": "Go",
        "type": "R_TRIG",
        "comment": "The start press"
      },
      {
        "name": "GoQ",
        "type": "BOOL",
        "initialValue": false,
        "comment": "One scan at the start press"
      },
      {
        "name": "LidGoneQ",
        "type": "BOOL",
        "initialValue": false,
        "comment": "One scan when the lid is taken"
      },
      {
        "name": "BaseLeftQ",
        "type": "BOOL",
        "initialValue": false,
        "comment": "The assembled base has left"
      },
      {
        "name": "SettleDone",
        "type": "BOOL",
        "initialValue": false,
        "comment": "SettleT elapsed"
      },
      {
        "name": "GripDone",
        "type": "BOOL",
        "initialValue": false,
        "comment": "GripT elapsed"
      },
      {
        "name": "LetGoDone",
        "type": "BOOL",
        "initialValue": false,
        "comment": "LetGoT elapsed"
      },
      {
        "name": "LidsFed",
        "type": "INT",
        "initialValue": 0,
        "comment": "Lids emitted"
      },
      {
        "name": "BasesFed",
        "type": "INT",
        "initialValue": 0,
        "comment": "Bases emitted"
      }
    ],
    "inputs": [
      {
        "name": "Start",
        "type": "BOOL",
        "address": "%I0.0",
        "comment": "StartButton.pressed: start the assembly"
      },
      {
        "name": "LidReady",
        "type": "BOOL",
        "address": "%I0.1",
        "comment": "LidEye.detect: a lid waits at the lid blade"
      },
      {
        "name": "BaseReady",
        "type": "BOOL",
        "address": "%I0.2",
        "comment": "BaseEye.detect: a base waits at the base blade"
      },
      {
        "name": "XAtMin",
        "type": "BOOL",
        "address": "%I0.3",
        "comment": "Pick1.xAtMin: the pad is over the lid belt"
      },
      {
        "name": "XAtMax",
        "type": "BOOL",
        "address": "%I0.4",
        "comment": "Pick1.xAtMax: the pad is over the base belt"
      },
      {
        "name": "YAtMin",
        "type": "BOOL",
        "address": "%I0.5",
        "comment": "Pick1.yAtMin: the pad is down"
      },
      {
        "name": "YAtMax",
        "type": "BOOL",
        "address": "%I0.6",
        "comment": "Pick1.yAtMax: the pad is up"
      },
      {
        "name": "Gripped",
        "type": "BOOL",
        "address": "%I0.7",
