        "type": "BOOL",
        "address": "%I1.0",
        "comment": "ModeButton.pressed: each press switches between manual and automatic"
      },
      {
        "name": "JogXPlus",
        "type": "BOOL",
        "address": "%I1.1",
        "comment": "JogXPlus.pressed: jog the pad toward the base belt"
      },
      {
        "name": "JogXMinus",
        "type": "BOOL",
        "address": "%I1.2",
        "comment": "JogXMinus.pressed: jog the pad toward the lid belt"
      },
      {
        "name": "JogYPlus",
        "type": "BOOL",
        "address": "%I1.3",
        "comment": "JogYPlus.pressed: jog the pad up"
      },
      {
        "name": "JogYMinus",
        "type": "BOOL",
        "address": "%I1.4",
        "comment": "JogYMinus.pressed: jog the pad down"
      }
