{
  "name": "ManualAuto",
  "description": "Two-axis assembly with a manual and an automatic mode.",
  "version": "1.0.0",
  "variables": {
    "local": [
      {
        "name": "Auto",
        "type": "BOOL",
        "initialValue": false,
        "comment": "The mode: FALSE is manual, TRUE is automatic; the machine powers up in manual"
      },
      {
        "name": "ToAuto",
        "type": "BOOL",
        "initialValue": false,
        "comment": "A mode press while in manual"
      },
      {
        "name": "ToManual",
        "type": "BOOL",
        "initialValue": false,
        "comment": "A mode press while in automatic"
      },
      {
        "name": "Begin",
        "type": "BOOL",
        "initialValue": false,
        "comment": "A Start press that counts: only in automatic"
      },
      {
        "name": "Active",
        "type": "BOOL",
        "initialValue": false,
        "comment": "The assembly is on"
      },
      {
        "name": "Step",
        "type": "INT",
        "initialValue": 0,
        "comment": "0 idle, 1 home, 2 wait, 3 settle, 4 lower, 5 grip, 6 lift, 7 carry, 8 lower, 9 release, 10 raise, 11 return, 12 done"
      },
      {
        "name": "Cycles",
        "type": "INT",
        "initialValue": 0,
        "comment": "Assemblies finished"
      },
      {
        "name": "FreeBase",
        "type": "BOOL",
        "initialValue": false,
        "comment": "The base blade is open and the assembled base is leaving"
      },
      {
        "name": "SettleT",
        "type": "TON",
        "comment": "Wait before the pad lowers on the lid"
      },
      {
        "name": "GripT",
        "type": "TON",
        "comment": "Wait for the vacuum to take hold"
      },
      {
        "name": "LetGoT",
        "type": "TON",
        "comment": "Wait for the lid to settle on the base"
      },
      {
        "name": "BaseLeft",
        "type": "TON",
        "comment": "Wait for the assembled base to leave"
      },
      {
        "name": "LidGone",
        "type": "F_TRIG",
        "comment": "The pad has taken the lid"
      },
      {
        "name": "Go",
        "type": "R_TRIG",
        "comment": "The start press"
      },
      {
        "name": "GoQ",
        "type": "BOOL",
        "initialValue": false,
        "comment": "One scan at the start press"
